  night: [
    { x: "المبادئ العامة للقانون (المادة 1/38(ج)): مصدر شكلي مستقل ومباشر يلي المعاهدات والعرف الدولي، وهي مصدر احتياطي لا أصلي (إجماع واضعي النص وفق الأعمال التحضيرية).", pg: "312" },
    { x: "لجأ إليها التحكيم الدولي منذ نهاية القرن الثامن عشر، تحديدًا منذ 1794 (المحاكم المختلطة الأمريكية الإنجليزية، معاهدات جاي)، لا منذ 1920 (المحكمة الدائمة للعدل الدولي) فقط.", pg: "312–313" },
    { x: "ثلاثة اتجاهات على الأقل: المبادئ العامة للقانون الدولي (جانب من الفقه)، ومبادئ التعايش السلمي، والراجح: المبادئ المشتركة بين مختلف النظم القانونية الداخلية.", pg: "313–316" },
    { x: "الاتجاه الأول: الميثاق (المادة الثانية) وقرار الجمعية العامة في 24 أكتوبر 1970؛ والثاني: المعاهدة الصينية الهندية (29 نوفمبر 1954) بخمسة مبادئ.", pg: "314–315" },
    { x: "يرفض المؤلف الاتجاهين الأولين لأنهما يجعلان الفقرة (ج) لا تضيف جديدًا، وإعمال النص خير من إهماله.", pg: "314–316" },
    { x: "«الأمم المتمدنة» اصطلاح منتقد من نظام المحكمة الدائمة للعدل الدولي (1920)، أغفلته المادة 1/21(ج) التي تستخلص المبادئ من التشريعات الوطنية الممثلة لمختلف النظم.", pg: "316–317" },
    { x: "شرطان: الاشتراك بين «مختلف» لا «جميع» النظم الداخلية، والقابلية للتطبيق على العلاقات الدولية؛ ونسبية آثار المبادئ العامة رأي المؤلف.", pg: "317–318" },
    { x: "194 دولة؛ نظامان رئيسيان: الأنجلوسكسوني (غير المكتوب والسوابق) واللاتيني الروماني (المكتوب والتشريع)؛ والتمثيل في التشكيل: المادة التاسعة (العدل الدولية) و8/36 (الجنائية) و2/2 (قانون البحار).", pg: "318–319" },
    { x: "لا يصلحان: حق اللجوء إلى القضاء بالإرادة المنفردة، والخصم والحكم (في بعض الحالات)؛ ويصلح مثلًا: منع التعسف في استخدام الحق، وحسن النية، وحسن الجوار، والقوة القاهرة، ولا قائمة حصرية.", pg: "320–321" },
    { x: "أحكام المحاكم والفقه (1/38(د) مع مراعاة المادة 59): مصدران استدلاليان لا ينشئان القواعد، لأن الدول والمنظمات الدولية لا تسمح لغيرهما بالدور التشريعي.", pg: "322–323" },
    { x: "أحكام المحاكم بمفهوم واسع: الدولية والداخلية، الدائمة والتحكيم (الغنيمي: الدولية فقط)؛ ودورها أكبر في العرف والمبادئ العامة؛ والمادة 2/21: استئناس بالقرارات السابقة لا تطبيق لها.", pg: "323–324" },
    { x: "الفقه يشمل الآراء الفردية والمخالفة للقضاة؛ الأوائل: جروسيوس وفاتل وكلسن، ثم روسو وفيرالي وفيشر، والعرب: الأوزاعي والشيباني (القرن الثامن الميلادي).", pg: "324–325" },
    { x: "العدل والإنصاف: المادتان 2/38 و2/293 (قانون البحار 1982) بموافقة الأطراف؛ بالموافقة: احتياطي يسد النقص، أو أصلي عند الإحلال (رأي المؤلف خلافًا لجانب من الفقه) ما لم يخالف الحل القواعد الآمرة.", pg: "326–328" },
    { x: "بدون موافقة الأطراف: صفة ملازمة للقانون يحققها القاضي من تلقاء نفسه، ووسيلة للتخفيف لا مصدر؛ الجرف القاري لبحر الشمال (محكمة العدل الدولية، 20 فبراير 1969).", pg: "329" }
  ],
